def insertion_sort(a: MutableSequence[int], lo: int = 0, hi: int | None = None) -> None:
    """就地对 a[lo:hi] 做插入排序。hi 为 None 时取到末尾。"""
    if hi is None:
        hi = len(a)
    # 边界条件：空区间或单元素区间天然有序，直接返回
    if hi - lo < 2:
        return

